targets.expr:
avg by (job,postgres_cluster,cluster,instance) (
  sum by (job,postgres_cluster,cluster,instance) (
  (
    pg_stat_user_tables_n_dead_tup{job=~"$job",postgres_cluster=~"$postgres_cluster",cluster=~"$cluster",instance=~"$instance"}
    /
    (pg_stat_user_tables_n_live_tup{job=~"$job",postgres_cluster=~"$postgres_cluster",cluster=~"$cluster",instance=~"$instance"} + pg_stat_user_tables_n_dead_tup{job=~"$job",postgres_cluster=~"$postgres_cluster",cluster=~"$cluster",instance=~"$instance"} + 1)
  ) > bool 0.1
)
/
count by (job,postgres_cluster,cluster,instance) (pg_stat_user_tables_n_live_tup{job=~"$job",postgres_cluster=~"$postgres_cluster",cluster=~"$cluster",instance=~"$instance"})

)
